/** DOM 도우미: 요소 만들기, 알림, 메뉴, 대화상자 */
import { icon } from './icons';
import { SHORT_HEIGHT, clampBox } from './layout';
import { decimalText } from '../datetext';
import { uiText } from '../i18n-text';

export function h<K extends keyof HTMLElementTagNameMap>(
  tag: K,
  attrs: Record<string, string | boolean | number | ((ev: Event) => void) | undefined> = {},
  ...children: (Node | string | null | undefined | false)[]
): HTMLElementTagNameMap[K] {
  const el = document.createElement(tag);
  for (const [k, v] of Object.entries(attrs)) {
    if (v === undefined || v === false) continue;
    if (typeof v === 'function') el.addEventListener(k.replace(/^on/, ''), v as EventListener);
    else if (k === 'class') el.className = String(v);
    else if (k === 'html') el.innerHTML = String(v);
    else if (v === true) el.setAttribute(k, '');
    else el.setAttribute(k, String(v));
  }
  for (const c of children) {
    if (c === null || c === undefined || c === false) continue;
    el.append(typeof c === 'string' ? document.createTextNode(c) : c);
  }
  return el;
}

export function iconSpan(name: string, cls = 'ic'): HTMLSpanElement {
  const s = document.createElement('span');
  s.className = cls;
  s.innerHTML = icon(name);
  return s;
}

let toastWrap: HTMLDivElement | null = null;
/**
 * 단추 없는 알림의 종류와 부른 쪽 글(271차 — 같은 알림을 하나로). 번역층(i18n.ts)이 떠 있는 알림의 글 마디를 번역 글로 바꾸므로
 * 화면 글이 아니라 이것으로 견준다
 */
const toastKeys = new WeakMap<Element, string>();
/**
 * 한 번에 보이는 단추 없는 알림 수(280차). 알림 영역은 최대 높이 없이 아래로 쌓여, 두 줄 알림 셋이 세로 휴대폰 화면 위 31~40%까지 오고 다섯이면 작은 화면의
 * 보기 모드 카드를 덮는다. 낮은 화면(가로로 눕힌 휴대폰 — CSS가 명령행 기록을 두 줄로 줄이는 높이)은 셋이면 66%라 둘
 */
const TOAST_LIMIT = 3;
const TOAST_LIMIT_SHORT = 2;

/** 알림에 붙는 단추(예: 새 버전 → 새로 고침) */
export interface ToastAction {
  label: string;
  run: () => void;
}

/**
 * 잠깐 보이는 알림. 오류는 화면 읽기 프로그램이 바로 읽게 role="alert"로 둔다.
 * action이 있으면 단추와 닫기 단추를 붙인다. ms가 0이면 닫을 때까지 남는다.
 * 단추 없는 알림은 같은 종류·같은 글의 단추 없는 알림이 떠 있으면 그것을 지우고 새로 붙인다(271차 — 쌓이지 않고 하나만, 시간은 마지막 알림부터).
 * 글이 다른 단추 없는 알림이 TOAST_LIMIT(낮은 화면은 TOAST_LIMIT_SHORT)를 넘으면 가장 오래된 것부터 지운다(280차).
 * text가 글을 만드는 함수면(349차 — 파일 크기 「1.5 KB」처럼 화면 언어 꼴 수가 든 알림) 떠 있는 채 언어를 바꿀 때 relangToasts가 그 함수로 새 꼴 글을 다시 쓴다
 */
export function toast(source: string | (() => string), kind: 'info' | 'warn' | 'error' = 'info', ms = 4200, action?: ToastAction): HTMLDivElement {
  const text = typeof source === 'function' ? source() : source;
  if (!toastWrap || !toastWrap.isConnected) {
    toastWrap = h('div', { class: 'toast-wrap', role: 'status', 'aria-live': 'polite' });
    document.body.append(toastWrap);
  }
  const t = h('div', { class: `toast ${kind === 'info' ? '' : kind}`, role: kind === 'error' ? 'alert' : undefined }, h('span', { class: 'toast-text' }, text));
  if (action) {
    t.classList.add('has-action');
    const run = h('button', { type: 'button', class: 'toast-action' }, action.label);
    run.addEventListener('click', () => {
      t.remove();
      action.run();
    });
    const close = h('button', { type: 'button', class: 'toast-close', 'aria-label': '알림 닫기', title: '알림 닫기', html: icon('close2') });
    close.addEventListener('click', () => t.remove());
    t.append(run, close);
  } else {
    // 같은 오류를 거듭 내면(보기 모드에서 비틀린 뷰포트를 거듭 두 번 누르기 등) 알림이 하나씩 쌓여 도면을 가렸다(271차). 옛 것의 시간만 늘리지 않고
    // 지운 뒤 새로 붙이는 까닭: 알림 영역(aria-live)·오류 알림(role="alert")은 새로 들어온 마디를 화면 읽기 프로그램이 다시 읽는다.
    // 옛 알림의 시간 재기는 그 요소만 지운다(이미 빠져 새 알림에 닿지 않음). 단추 있는 알림은 사용자가 처리할 때까지 쌓아 둔다
    const key = `${kind}\n${text}`;
    for (const old of Array.from(toastWrap.children)) if (toastKeys.get(old) === key) old.remove();
    toastKeys.set(t, key);
  }
  toastWrap.append(t);
  if (!action) {
    // 글이 다른 알림(참조 파일 고르기·여러 파일 열기에서 파일마다 다른 오류 등)은 위에서 묶이지 않아 수 한도 없이 쌓였다(280차). 새 알림은 맨 뒤라 남아
    // 화면 읽기 프로그램이 읽고, 오래된 것부터 빠진다. 오류 알림은 명령행 기록에도 남는다(보기 모드 명령 밖 오류 줄·열기 실패·받기 실패(281차) — 부르는 쪽이 적음).
    // 단추 있는 알림은 지우지도 세지도 않는다. 같은 글은 위에서 옛 것이 빠져 수가 그대로다
    const plain = Array.from(toastWrap.children).filter((c) => toastKeys.has(c));
    const limit = window.innerHeight < SHORT_HEIGHT ? TOAST_LIMIT_SHORT : TOAST_LIMIT;
    for (const old of plain.slice(0, Math.max(0, plain.length - limit))) old.remove();
  }
  if (typeof source === 'function') toastSources.set(t, { kind, make: source });
  if (ms > 0) setTimeout(() => t.remove(), ms);
  return t;
}

/** 글을 만드는 함수로 띄운 알림(349차) — 빠진 알림은 relangToasts가 지운다 */
const toastSources = new Map<HTMLElement, { kind: string; make: () => string }>();

/**
 * 화면 언어를 바꾼 뒤(349차 — Shell.relang이 languagechange에서 부른다): 함수로 띄운 알림 가운데 떠 있는 것의 글을 새 꼴로 다시 쓴다.
 * 번역층은 글 마디를 원문으로 다시 옮기지만 틀 {0}에 넣은 수(「1.5 KB」 ↔ 독일어 「1,5 KB」)는 넣은 때 꼴 그대로라서. 다시 쓴 한국어 글은 번역층이 새 언어로 옮긴다
 */
export function relangToasts(): void {
  for (const [t, { kind, make }] of toastSources) {
    if (!t.isConnected) {
      toastSources.delete(t);
      continue;
    }
    const text = make();
    t.querySelector('.toast-text')!.textContent = text;
    // 같은 글 알림 묶기(271차)도 새 글로
    if (toastKeys.has(t)) toastKeys.set(t, `${kind}\n${text}`);
  }
}

/** 키보드로 초점을 옮겨 온 요소인지(:focus-visible — 마우스로 누른 단추는 아니다). 이 판별을 못 하는 환경은 false */
export function focusVisible(el: Element): boolean {
  try {
    return el.matches(':focus-visible');
  } catch {
    return false;
  }
}

/** 키보드로 초점을 옮겨 온 단추·링크·탭 같은 컨트롤인지(그림 영역·문서 본문은 아니다). 앱의 Enter·Space·Tab 처리가 이것을 비켜 간다 */
export function keyboardControl(t: Element | null): boolean {
  if (!t || typeof t.matches !== 'function' || t === document.body || t.tagName === 'CANVAS') return false;
  return t.matches('button, a[href], summary, select, [role="button"], [role="tab"], [role="menuitem"], [role="option"], [tabindex]') && focusVisible(t);
}

/**
 * 가로 탭 줄의 키보드 옮기기(W3C APG 탭 꼴 — 리본 탭·도면 탭·팔레트 탭(259차)과 관리·치수 스타일·참조 편집 대화 상자·디자인센터·블록 팔레트 탭(260차)·배치 탭(261차)이
 * 함께 쓴다): 지금 탭 i(탭 n개)에서 왼쪽·오른쪽 화살표(끝에서 돌아감)·
 * Home·End로 옮겨 갈 탭 차례, 아니면 -1. Alt·Ctrl·Meta·Shift와 함께 누른 키도 -1 — 탭이 가로채지 않아 Alt+←·→(브라우저 뒤로·앞으로)·Ctrl+Home 같은
 * 브라우저·앱 단축키가 그대로 닿는다(APG 탭 꼴은 수정 키 없는 화살표만). 고르기(자동·수동)는 부르는 쪽이 정한다
 */
export function tabKeyTarget(ev: Pick<KeyboardEvent, 'key' | 'altKey' | 'ctrlKey' | 'metaKey' | 'shiftKey'>, i: number, n: number): number {
  if (ev.altKey || ev.ctrlKey || ev.metaKey || ev.shiftKey) return -1;
  const k = ev.key;
  return k === 'ArrowRight' ? (i + 1) % n : k === 'ArrowLeft' ? (i - 1 + n) % n : k === 'Home' ? 0 : k === 'End' ? n - 1 : -1;
}

/** 키보드로 옮겨 다닐 수 있는(보이는) 요소들 */
export function focusables(root: ParentNode): HTMLElement[] {
  const sel = 'a[href], button:not([disabled]), input:not([disabled]):not([type="hidden"]), select:not([disabled]), textarea:not([disabled]), summary, [tabindex]:not([tabindex="-1"]), [contenteditable="true"]';
  return [...root.querySelectorAll<HTMLElement>(sel)].filter(shown);
}

/**
 * 보이는지: [hidden]·[inert] 안이거나 display none·visibility hidden이면 숨음(focusables·메뉴를 닫을 때 연 단추 — 264차).
 * 계산된 꼴을 읽지 못하는 환경(window만 가짜인 시험)은 속성만 본다(overlay-place.ts 꼴)
 */
function shown(el: HTMLElement): boolean {
  if (el.closest('[hidden], [inert]')) return false;
  if (typeof getComputedStyle !== 'function') return true;
  const cs = getComputedStyle(el);
  return cs.display !== 'none' && cs.visibility !== 'hidden';
}

/** 초점을 받을 수 있는지: 문서에 붙어 있고, 막히지 않았고(:disabled), 보인다(289차) */
function canFocus(el: HTMLElement): boolean {
  return el.isConnected && !el.matches(':disabled') && shown(el);
}

/**
 * 누른 단추가 그 누름 때문에 막히거나(disabled) 숨거나(hidden) 문서에서 빠진 뒤의 초점(289차 — WCAG 2.4.3 초점 순서): 초점이 있던 요소가 막히거나 숨으면
 * 브라우저의 focus fixup이 초점을 문서(body)로 옮기고, 떼어 낸 요소도 초점을 잃어 초점 표시가 사라지고 Enter·Space가 듣지 않으며 키보드 사용자가 제자리를 잃는다.
 * held는 누르기 처리를 시작할 때 초점이 있던 요소(document.activeElement). held가 from 가운데 하나이고 이제 초점을 받을 수 없으며, 초점이 문서로 빠졌거나
 * held에 남았을 때만 to에서 처음으로 초점을 받는 것에 준다(막혔거나 숨은 것은 건너뛴다, 화면은 옮기지 않음). 초점이 다른 곳(새로 연 상자 등)에 있거나
 * held가 아직 초점을 받을 수 있으면 그대로 — 마우스로 눌러 단추가 초점을 받지 않는 브라우저(Safari·iOS)는 held가 그 단추가 아니라 그대로다. 준 곳이 있으면 true
 */
export function refocusStuck(held: Element | null, from: readonly (Element | null | undefined)[], to: readonly (HTMLElement | null | undefined)[]): boolean {
  if (!held || !from.includes(held) || canFocus(held as HTMLElement)) return false;
  const now = document.activeElement;
  if (now && now !== document.body && now !== held && now.isConnected) return false;
  for (const el of to) {
    if (!el || !canFocus(el)) continue;
    el.focus({ preventScroll: true });
    if (document.activeElement === el) return true;
  }
  return false;
}

export interface MenuItem {
  label?: string;
  icon?: string;
  kbd?: string;
  disabled?: boolean;
  separator?: boolean;
  heading?: string;
  run?: () => void;
  /** 마우스가 올라갈 때(선택 순환의 강조 등) */
  hover?: () => void;
}

let openMenu: HTMLDivElement | null = null;
/** 연 단추(showMenu opt.opener), 없으면 메뉴를 열기 전에 초점이 있던 곳(Esc·Tab·항목 고르기로 닫으면 돌려준다) */
let menuOpener: HTMLElement | null = null;
/** 연 단추가 숨었을 때 대신 돌려줄 곳: 메뉴를 열기 전에 초점이 있던 곳(264차 — 좁은 화면에서 상태 막대 「⋯」 메뉴로 연 「▾」·주석 축척 메뉴는 그 「⋯」) */
let menuFallback: HTMLElement | null = null;
/** 지금 메뉴가 닫힐 때 부를 것(항목을 고르든 Esc·바깥 누르기·다른 메뉴로 닫히든) */
let menuClosed: (() => void) | null = null;
/** 메뉴 이름을 잇는 id(연 단추·머리글에 id가 없을 때) */
let menuNameSeq = 0;

export function closeMenu(restoreFocus = false): void {
  const had = !!openMenu;
  openMenu?.remove();
  openMenu = null;
  if (had && restoreFocus && menuOpener?.isConnected) {
    // 연 단추가 붙어 있지만 보이지 않으면(좁은 화면에서 「⋯」 메뉴로 옮겨 숨은 단추 — 그 단추에는 초점을 줄 수 없어 본문으로 빠졌다) 열기 전 초점(그 「⋯」)으로.
    // 그것도 없거나 숨었으면 지금처럼 연 단추
    const back = !shown(menuOpener) && menuFallback?.isConnected && shown(menuFallback) ? menuFallback : menuOpener;
    back.focus({ preventScroll: true });
  }
  menuOpener = null;
  menuFallback = null;
  const done = menuClosed;
  menuClosed = null;
  done?.();
}

/**
 * 열린 메뉴의 연 단추가 from 안이면 닫을 때(Esc·Tab·항목 고르기) 초점을 돌려줄 곳을 to로 바꾼다(283차 — 접힌 리본 패널 팝업 안 펼침 단추(▾)로 연 메뉴:
 * 팝업이 닫히며 그 단추가 문서에서 빠져, 메뉴를 닫으면 초점이 본문으로 갔다. 위 「숨은 연 단추면 열기 전 초점」(264차)은 붙어 있는 단추만 다룬다 —
 * 열기 전 초점도 같은 팝업 안이라 함께 빠지므로 비운다)
 */
export function moveMenuOpener(from: Node, to: HTMLElement): void {
  if (!openMenu || !menuOpener || !from.contains(menuOpener)) return;
  menuOpener = to;
  if (menuFallback && from.contains(menuFallback)) menuFallback = null;
}

/**
 * 메뉴 항목의 이름: 단추 바로 아래 글 마디(번역층이 그 자리에서 바꾼 화면 글 — 아이콘·단축키 kbd는 뺌). 맨 앞의 켜짐 표시 「✓」는 상태라 뗀다.
 * 글 마디는 3으로 가린다(Node 전역이 없는 시험 환경)
 */
function itemName(b: HTMLElement): string {
  let s = '';
  for (const n of Array.from(b.childNodes)) if (n.nodeType === 3) s += n.nodeValue ?? '';
  return s.trim().replace(/^✓\s*/u, '');
}

/**
 * 첫 글자 찾기(265차 — W3C APG 메뉴 꼴): 인쇄 가능한 한 글자 key로 이름이 시작하는 다음 항목의 차례(지금 i 다음부터 돌아 i까지 — 하나뿐이면 i), 없으면 -1.
 * 대소문자는 가리지 않는다(APG 예제와 같음 — 영어 항목은 대문자로 시작하고 글자 키는 소문자를 낸다). 한글은 음절 그대로 견준다(초성 찾기 없음).
 * 빈칸(Space는 고르기)·이름 키(Process 등 입력기 키)는 -1
 */
function typeAhead(list: HTMLElement[], i: number, key: string): number {
  if ([...key].length !== 1 || !/\S/u.test(key)) return -1;
  const want = key.toLowerCase();
  const n = list.length;
  for (let j = 1; j <= n; j++) {
    const at = (i + j + n) % n;
    const first = [...itemName(list[at]!)][0];
    if (first !== undefined && first.toLowerCase() === want) return at;
  }
  return -1;
}

/**
 * 바로가기 메뉴. 키보드: 위·아래 화살표·Home·End로 옮기고 Enter·Space로 고르며, Esc는 닫고 연 곳으로 초점을 돌린다(Tab도 닫는다).
 * 글자 한 자를 치면 그 글자로 이름이 시작하는 다음 켜진 항목으로 옮긴다(265차 — 같은 글자를 다시 치면 그다음, 끝에서 처음으로, 없으면 그대로.
 * 고르지는 않는다. Ctrl·Alt·⌘와 함께 친 글자는 브라우저·앱 단축키로 넘긴다).
 * 열면 첫 켜진 항목에 초점을 둔다 — 키보드로 연 메뉴도, 손가락·마우스로 누르거나 오른쪽 클릭해 연 메뉴도(262차 — W3C APG 메뉴 단추 꼴, WCAG 2.4.3.
 * 전에는 키보드로 연 메뉴만 옮겨, 화면 읽기 프로그램의 두 번 톡(click)으로 연 메뉴는 초점이 밖에 남았다). 보이는 초점 표시는 :focus-visible 규칙대로
 * (styles.css — 손가락·마우스로 연 메뉴에는 그리지 않는다). opt.hover(커서를 올리면 뜨는 메뉴 — 다기능 그립)는 지금처럼 키보드로 옮긴 초점이 있을 때만.
 * 켜진 항목이 없는 메뉴는 메뉴 자체에 초점을 둔다(263차 — Esc·Tab으로 닫을 수 있게).
 * opt.opener는 연 단추: 누르기로 초점을 받지 않는 브라우저(Safari·iOS)에서도 닫을 때 그 단추로 돌려준다(없으면 열 때의 초점). 그 단추가 숨었으면
 * 열 때의 초점으로(264차 — 상태 막대 「⋯」 메뉴로 옮긴 「▾」·주석 축척). 메뉴 이름도 그 단추로 잇는다(264차 — aria-labelledby, W3C APG 메뉴 단추 꼴).
 * 연 단추가 없는 메뉴는 맨 앞 머리글이 그 메뉴의 하나뿐인 머리글이면 그것이 이름이다(여럿이면 묶음 이름이라 이름 없음).
 * 메뉴 단추(aria-haspopup="menu")는 onClose로 aria-expanded를 false로 되돌리고 연 뒤에 true로 둔다(253·254·263차 — 부르는 쪽).
 * onClose는 메뉴가 닫힐 때 한 번(항목의 run보다 먼저)
 */
export function showMenu(x: number, y: number, items: MenuItem[], opt: { onClose?: () => void; opener?: HTMLElement; hover?: boolean } = {}): void {
  closeMenu();
  const active = document.activeElement instanceof HTMLElement && document.activeElement !== document.body ? document.activeElement : null;
  const opener = opt.opener ?? active;
  const m = h('div', { class: 'menu', role: 'menu' });
  const heads: HTMLElement[] = [];
  for (const it of items) {
    if (it.separator) {
      m.append(h('hr', { role: 'separator' }));
      continue;
    }
    if (it.heading) {
      const head = h('div', { class: 'label', role: 'presentation' }, it.heading);
      heads.push(head);
      m.append(head);
      continue;
    }
    const b = h(
      'button',
      {
        type: 'button',
        role: 'menuitem',
        tabindex: -1,
        disabled: !!it.disabled,
        onclick: () => {
          closeMenu(true);
          it.run?.();
        },
        onmouseenter: () => it.hover?.(),
      },
      it.icon ? iconSpan(it.icon) : h('span', { class: 'ic' }),
      it.label ?? '',
      it.kbd ? h('kbd', {}, it.kbd) : null,
    );
    m.append(b);
  }
  // 메뉴 이름(264차 — WCAG 4.1.2): 연 단추(id가 없으면 새로), 없으면 하나뿐인 맨 앞 머리글. 열 때의 초점(오른쪽 클릭 길)은 이름에 쓰지 않는다.
  // 숨은 연 단추도 aria-labelledby가 직접 가리키면 이름 셈에 든다(접근 이름 계산 규칙)
  const named = opt.opener ?? (heads.length === 1 && m.firstElementChild === heads[0] ? heads[0] : null);
  if (named) {
    if (!named.id) named.id = `menu-name-${++menuNameSeq}`;
    m.setAttribute('aria-labelledby', named.id);
  }
  const enabled = () => [...m.querySelectorAll<HTMLButtonElement>('button[role="menuitem"]:not([disabled])')];
  m.addEventListener('keydown', (ev) => {
    const k = ev as KeyboardEvent;
    const list = enabled();
    const i = list.indexOf(document.activeElement as HTMLButtonElement);
    let next = -1;
    if (k.key === 'ArrowDown') next = (i + 1) % list.length;
    else if (k.key === 'ArrowUp') next = (i - 1 + list.length) % list.length;
    else if (k.key === 'Home') next = 0;
    else if (k.key === 'End') next = list.length - 1;
    else if (k.key === 'Escape') {
      k.preventDefault();
      k.stopPropagation();
      closeMenu(true);
      return;
    } else if (k.key === 'Tab') {
      closeMenu(true);
      return;
    } else if (!k.ctrlKey && !k.altKey && !k.metaKey && !k.isComposing) next = typeAhead(list, i, k.key);
    if (next >= 0 && list.length) {
      k.preventDefault();
      k.stopPropagation();
      list[next]!.focus();
    }
  });
  document.body.append(m);
  const r = m.getBoundingClientRect();
  // 보이는 영역(소프트 키보드가 올라오면 그만큼 줄어든다) 안에 둔다. 데스크톱에서는 창 크기와 같다
  const vv = window.visualViewport;
  const ox = vv?.offsetLeft ?? 0;
  const oy = vv?.offsetTop ?? 0;
  const pos = clampBox(x - ox, y - oy, r.width, r.height, vv?.width ?? window.innerWidth, vv?.height ?? window.innerHeight);
  m.style.left = `${pos.left + ox}px`;
  m.style.top = `${pos.top + oy}px`;
  openMenu = m;
  menuOpener = opener;
  menuFallback = opt.opener && active !== opt.opener ? active : null;
  menuClosed = opt.onClose ?? null;
  // 메뉴 안 첫 켜진 항목으로. 커서를 올려 연 메뉴는 키보드로 옮긴 초점이 있던 곳에서만 — 누르지 않고 뜨는 메뉴가 치던 자리의 초점을 빼앗지 않게.
  // 켜진 항목이 없으면 메뉴 자체(tabindex -1)에(263차 — 위 키 처리는 메뉴 안의 초점만 받아, 초점이 밖에 남으면 Esc로 닫을 수 없었다. 화살표는 옮길 곳이 없어 그대로).
  // 초점 표시는 대화 상자(tabindex -1 상자)처럼 브라우저 기본 — 앱의 :focus-visible 규칙은 tabindex -1을 빼고, 키보드로 연 메뉴에만 그려진다
  if (!opt.hover || (active && focusVisible(active))) {
    const first = enabled()[0];
    if (first) first.focus();
    else {
      m.tabIndex = -1;
      m.focus();
    }
  }
  setTimeout(() => {
    const off = (ev: Event) => {
      if (openMenu && !openMenu.contains(ev.target as Node)) {
        closeMenu();
        window.removeEventListener('pointerdown', off, true);
      }
    };
    window.addEventListener('pointerdown', off, true);
  });
}

let dialogSeq = 0;

/**
 * 대화상자(모달). 키보드: 열면 주 단추(없으면 상자)에 초점, Tab·Shift+Tab은 상자 안에서만 돈다, Esc는 닫는다.
 * 어떻게 닫히든(단추·Esc·바깥 누르기·back.remove()) 열기 전에 초점이 있던 곳으로 초점을 돌린다
 */
export function dialog(title: string, body: Node | string, buttons: { label: string; primary?: boolean; run?: () => void | boolean }[] = [{ label: '닫기', primary: true }]): HTMLDivElement {
  const opener = document.activeElement instanceof HTMLElement && document.activeElement !== document.body ? document.activeElement : null;
  const back = h('div', { class: 'dialog-back' });
  const close = () => back.remove();
  const titleId = `dialog-title-${++dialogSeq}`;
  const box = h(
    'div',
    // 이름은 aria-label(제목과 같은 글 — 다른 코드·시험이 이것으로 상자를 찾는다), 제목은 h2로 둬 화면 읽기 프로그램의 제목 이동에도 잡힌다
    { class: 'dialog', role: 'dialog', 'aria-modal': 'true', 'aria-label': title, tabindex: -1 },
    h('header', {}, h('h2', { class: 'dialog-title', id: titleId }, title), h('button', { type: 'button', class: 'icon-btn', 'aria-label': '닫기', title: '닫기', onclick: close, html: icon('close2') })),
    h('div', { class: 'body' }, typeof body === 'string' ? h('div', { html: body }) : body),
    h(
      'footer',
      {},
      ...buttons.map((b) =>
        h(
          'button',
          {
            type: 'button',
            class: `btn ${b.primary ? 'primary' : ''}`,
            onclick: () => {
              const keep = b.run?.();
              if (keep !== true) close();
            },
          },
          b.label,
        ),
      ),
    ),
  );
  back.append(box);
  back.addEventListener('pointerdown', (ev) => {
    if (ev.target === back) close();
  });
  back.addEventListener('keydown', (ev) => {
    const k = ev as KeyboardEvent;
    if (k.key === 'Escape') {
      // 명령 중에 연 도움말 같은 상자를 Esc로 닫아도 진행 중인 명령은 그대로 둔다
      k.preventDefault();
      k.stopPropagation();
      close();
      return;
    }
    if (k.key !== 'Tab') return;
    const list = focusables(box);
    if (!list.length) {
      k.preventDefault();
      box.focus();
      return;
    }
    const first = list[0]!;
    const last = list[list.length - 1]!;
    const cur = document.activeElement;
    if (k.shiftKey && (cur === first || cur === box || !box.contains(cur))) {
      k.preventDefault();
      last.focus();
    } else if (!k.shiftKey && (cur === last || !box.contains(cur))) {
      k.preventDefault();
      first.focus();
    }
  });
  document.body.append(back);
  const obs = new MutationObserver(() => {
    if (back.isConnected) return;
    obs.disconnect();
    const now = document.activeElement;
    if (opener?.isConnected && (!now || now === document.body || !now.isConnected)) opener.focus({ preventScroll: true });
  });
  obs.observe(document.body, { childList: true });
  ((box.querySelector('footer .btn.primary') as HTMLButtonElement | null) ?? box).focus();
  return back;
}

export function escapeHtml(s: string): string {
  return s.replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]!);
}

/** 파일 크기 글(셈 소수 — 소수점은 화면 언어 꼴: 독일어 「1,5 KB」, 348차) */
export function formatBytes(n: number): string {
  if (n < 1024) return `${n} B`;
  if (n < 1024 * 1024) return `${decimalText(n / 1024, 1)} KB`;
  return `${decimalText(n / 1024 / 1024, 1)} MB`;
}

/** 버튼을 고르게 하는 질문 상자(닫으면 null) */
export function ask<T extends string>(title: string, text: string, buttons: { label: string; value: T; primary?: boolean }[]): Promise<T | null> {
  return new Promise((resolve) => {
    let done = false;
    const back = dialog(
      title,
      h('div', {}, text),
      buttons.map((b) => ({
        label: b.label,
        primary: b.primary,
        run: () => {
          done = true;
          resolve(b.value);
        },
      })),
    );
    const obs = new MutationObserver(() => {
      if (!back.isConnected) {
        obs.disconnect();
        if (!done) resolve(null);
      }
    });
    obs.observe(document.body, { childList: true });
  });
}

export type FormField =
  /**
   * list: 고를 수 있는 값(입력 칸에 목록으로 뜬다 — 다른 값도 칠 수 있다).
   * signed: 음수도 받는 숫자 칸(각도·간격띄우기 등 — 288차). 숫자 칸은 휴대폰·태블릿에 소수 자판(inputmode="decimal")을 띄우는데
   * 그 자판은 음수 기호를 약속하지 않아 signed 칸에는 두지 않는다(일반 글 자판). 값 읽기·검사는 같다
   */
  | { key: string; label: string; type: 'text' | 'number'; value: string | number; placeholder?: string; wide?: boolean; list?: readonly string[]; signed?: boolean }
  | { key: string; label: string; type: 'select'; value: string; options: { value: string; label: string }[] }
  | { key: string; label: string; type: 'check'; value: boolean }
  | { key: string; label: string; type: 'textarea'; value: string }
  /**
   * 부른 쪽이 만든 칸(단추가 있는 목록 등 — 키는 그 칸이 받는다, Enter로 상자를 확인하지 않는다). read: 돌려줄 값(글).
   * check: 확인 직전에 부른다(넣다 만 값을 넣어 보고, 안 되면 문구 — 상자를 닫지 않는다)
   */
  | { key: string; label: string; type: 'custom'; el: HTMLElement; read: () => string; check?: () => string | null };

let formListSerial = 0;

/** 입력 칸 여러 개를 받는 대화상자(취소하면 null). check는 boolean, number는 숫자로 돌려준다 */
export function form(title: string, fields: FormField[], opt: { ok?: string; note?: string; validate?: (v: Record<string, string | number | boolean>) => string | null } = {}): Promise<Record<string, string | number | boolean> | null> {
  return new Promise((resolve) => {
    let done = false;
    const inputs = new Map<string, HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>();
    const err = h('div', { class: 'form-error', role: 'alert' });
    const rows = fields.map((f) => {
      if (f.type === 'custom') {
        // 단추를 담은 칸은 <label>로 감싸지 않는다(이름표를 누르면 첫 단추가 눌린다). 이름은 칸 안의 요소가 스스로 단다
        return h('div', { class: 'form-row custom' }, h('span', {}, f.label), f.el);
      }
      let el: HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement;
      if (f.type === 'select') {
        el = h('select', { 'aria-label': f.label }, ...f.options.map((o) => h('option', { value: o.value }, o.label)));
        el.value = f.value;
      } else if (f.type === 'check') {
        el = h('input', { type: 'checkbox', 'aria-label': f.label });
        (el as HTMLInputElement).checked = f.value;
      } else if (f.type === 'textarea') {
        el = h('textarea', { 'aria-label': f.label, rows: 4 });
        el.value = f.value;
      } else {
        el = h('input', { type: f.type === 'number' ? 'text' : 'text', inputmode: f.type === 'number' && !f.signed ? 'decimal' : undefined, 'aria-label': f.label, placeholder: f.placeholder ?? '' });
        el.value = String(f.value);
      }
      // 고를 수 있는 값 목록(입력 칸 + datalist — 다른 값도 칠 수 있다)
      const list = 'list' in f && f.list?.length ? h('datalist', { id: `form-list-${++formListSerial}` }, ...f.list.map((v) => h('option', { value: v }))) : null;
      if (list) el.setAttribute('list', list.id);
      inputs.set(f.key, el);
      el.addEventListener('keydown', (ev) => {
        const k = ev as KeyboardEvent;
        k.stopPropagation();
        if (k.key === 'Enter' && f.type !== 'textarea') submit();
      });
      return h('label', { class: `form-row ${f.type === 'check' ? 'check' : ''}` }, h('span', {}, f.label), el, list);
    });
    const read = () => {
      const out: Record<string, string | number | boolean> = {};
      for (const f of fields) {
        if (f.type === 'custom') {
          out[f.key] = f.read();
          continue;
        }
        const el = inputs.get(f.key)!;
        if (f.type === 'check') out[f.key] = (el as HTMLInputElement).checked;
        else if (f.type === 'number') out[f.key] = Number(el.value.trim());
        else out[f.key] = el.value;
      }
      return out;
    };
    const submit = () => {
      for (const f of fields) {
        const e = f.type === 'custom' ? (f.check?.() ?? null) : null;
        if (e) {
          err.textContent = e;
          return;
        }
      }
      const v = read();
      for (const f of fields) {
        if (f.type === 'number' && !Number.isFinite(v[f.key] as number)) {
          // 칸 이름표는 앱 낱말: 틀 「{0}: 숫자를 입력하십시오.」의 {0}은 번역층이 옮기지 않아 네 언어에서 한국어로 남았다 — 화면 언어로 끼운다(342차)
          err.textContent = `${uiText(f.label)}: 숫자를 입력하십시오.`;
          return;
        }
      }
      const e = opt.validate?.(v) ?? null;
      if (e) {
        err.textContent = e;
        return;
      }
      done = true;
      back.remove();
      resolve(v);
    };
    const body = h('div', { class: 'form' }, ...rows, opt.note ? h('div', { class: 'form-note' }, opt.note) : null, err);
    const back = dialog(title, body, [
      { label: '취소', run: () => undefined },
      { label: opt.ok ?? '확인', primary: true, run: () => (submit(), true) },
    ]);
    const obs = new MutationObserver(() => {
      if (!back.isConnected) {
        obs.disconnect();
        if (!done) resolve(null);
      }
    });
    obs.observe(document.body, { childList: true });
    setTimeout(() => {
      const first = inputs.values().next().value as HTMLElement | undefined;
      first?.focus();
      if (first instanceof HTMLInputElement) first.select();
    });
  });
}
