/**
 * 특성·표시 명령: CHPROP, CHANGE(-CH), COLOR(COL), DDPTYPE(PTYPE), ATTDISP, SOLID(SO), TIME
 * 프롬프트는 AutoCAD 2026 한국어판을 따른다.
 */
import type { AttribEntity, CadColor, Entity, FaceEntity, HeaderValue, InsertEntity, Vec3 } from '../core/model';
import { tableKey } from '../core/model';
import { numberAngleDegrees } from '../core/units';
import { type EditOp, cloneEntity } from '../edit/session';
import { type Affine, affApply, affDet, affInv, affLin, affMul, affRotate, affTranslate } from '../edit/geom/math';
import { planProj } from '../edit/geom/ocs';
import { nearestLineweight } from '../edit/layercmd';
import { STANDARD_LINETYPES, makeLinetype } from '../edit/linetypes';
import type { App, CommandContext } from './app';
import { dateTimeText, drawingTimeText } from './datetext';
import type { DocState } from './docstate';
import { addEntities, currentElevation, currentProps } from './draw';
import { form } from './ui/dom';
import { ft } from './filetext';
import { uiText } from './i18n-text';

type Pt = { x: number; y: number };

const COLOR_NAMES: Record<string, number> = {
  RED: 1, 빨간색: 1, 빨강: 1,
  YELLOW: 2, 노란색: 2, 노랑: 2,
  GREEN: 3, 초록색: 3, 초록: 3,
  CYAN: 4, 하늘색: 4,
  BLUE: 5, 파란색: 5, 파랑: 5,
  MAGENTA: 6, 선홍색: 6,
  WHITE: 7, 흰색: 7,
  BYLAYER: 256, 도면층별: 256,
  BYBLOCK: 0, 블록별: 0,
};

/** 색 입력: 번호(0~256), 이름, BYLAYER·BYBLOCK, "r,g,b"(트루컬러) */
export function parseColorInput(t: string): CadColor | null {
  const s = t.trim();
  const up = s.toUpperCase();
  if (up in COLOR_NAMES) return { aci: COLOR_NAMES[up]! };
  if (s in COLOR_NAMES) return { aci: COLOR_NAMES[s]! };
  if (/^\d+$/.test(s)) {
    const n = Number(s);
    return n >= 0 && n <= 256 ? { aci: n } : null;
  }
  const rgb = /^(\d{1,3}),(\d{1,3}),(\d{1,3})$/.exec(s.replace(/\s+/g, ''));
  if (rgb) {
    const [r, g, b] = [rgb[1], rgb[2], rgb[3]].map(Number) as [number, number, number];
    if (r > 255 || g > 255 || b > 255) return null;
    return { aci: 7, rgb: (r << 16) | (g << 8) | b };
  }
  return null;
}

const colorLabel = (c: CadColor) => (c.rgb !== undefined ? `${(c.rgb >> 16) & 255},${(c.rgb >> 8) & 255},${c.rgb & 255}` : c.aci === 256 ? 'BYLAYER' : c.aci === 0 ? 'BYBLOCK' : String(c.aci));

function setHeader(st: DocState, ctx: CommandContext | null, label: string, name: string, value: HeaderValue): void {
  const before = st.doc.header.get(name);
  if (before === value) return;
  st.session.commit({ label, ops: [{ kind: 'header', name, before, after: value }], group: ctx?.group });
}

/** 고른 객체들을 같은 방식으로 바꾼다(pre: 바꾼 객체가 있을 때 같은 명령 취소 단계에 앞서 넣을 작업 — 선종류 로드 등) */
function modifyAll(st: DocState, ctx: CommandContext, label: string, hs: string[], f: (e: Entity) => Entity | null, pre: EditOp[] = []): number {
  const ops: EditOp[] = [];
  for (const h of hs) {
    const e = st.doc.entityIndex.get(h);
    const block = e ? st.session.ownerOf(h) : null;
    if (!e || !block) continue;
    const after = f(e);
    // 자리 짐작(108차 — 큰 선택의 특성 바꾸기가 적용 때 블록 전체의 자리 표를 만들지 않게)
    if (after) ops.push(st.session.hinted({ kind: 'modify', block, before: e, after }));
  }
  if (ops.length) st.session.commit({ label, ops: [...pre, ...ops], group: ctx.group });
  return ops.length;
}

/** CHPROP·CHANGE 특성(P) 공통: 특성을 하나씩 묻고 바꾼다 */
async function changeProps(app: App, ctx: CommandContext, hs: string[], label: string): Promise<void> {
  const st = app.active!;
  for (;;) {
    const r = await ctx.getPoint('변경할 특성 입력 [색상(C)/도면층(LA)/선종류(LT)/선종류 축척(S)/선가중치(LW)/두께(T)/투명도(TR)]:', {
      keywords: [
        { key: 'C', label: '색상' },
        { key: 'LA', label: '도면층' },
        { key: 'LT', label: '선종류' },
        { key: 'S', label: '선종류 축척' },
        { key: 'LW', label: '선가중치' },
        { key: 'T', label: '두께' },
        { key: 'TR', label: '투명도' },
      ],
    });
    if (!('keyword' in r)) return;
    const ask = async (prompt: string) => {
      const t = await ctx.getPoint(prompt, { allowText: true, preferNumber: true });
      return 'text' in t ? t.text.trim() : null;
    };
    switch (r.keyword) {
      case 'C': {
        const t = await ask('새 색상 [트루컬러(T)/색상표(CO)] <BYLAYER>:');
        const c = parseColorInput(t ?? 'BYLAYER');
        if (!c) ctx.print('색상 이름이나 번호(1~255), BYLAYER, BYBLOCK 또는 빨강,초록,파랑 값을 입력하십시오.', 'err');
        else modifyAll(st, ctx, label, hs, (e) => ({ ...e, color: c }) as Entity);
        break;
      }
      case 'LA': {
        const t = await ask('새 도면층 이름 입력:');
        const L = t ? st.doc.layers.get(tableKey(t)) : undefined;
        if (!L) ctx.print(`도면층 "${ft(t ?? '')}"을(를) 찾을 수 없습니다.`, 'err');
        else modifyAll(st, ctx, label, hs, (e) => ({ ...e, layer: L.name }) as Entity);
        break;
      }
      case 'LT': {
        const t = await ask('새 선종류 이름 입력 <BYLAYER>:');
        const name = t || 'ByLayer';
        const k = tableKey(name);
        // 로드되지 않은 선종류는 표준 선종류 정의에서 올린다(202차, Autodesk CHPROP·CHANGE 도움말 「선종류」: 표준 선종류 라이브러리 파일에서
        // 로드를 시도하고 실패하면 LINETYPE으로 로드). 정의 꼴은 -LINETYPE 로드·CENTERMARK처럼 $MEASUREMENT(1 = ISO mm, 0 = ANSI 인치, 없으면 1).
        // 로드와 객체 바꾸기는 명령 취소 한 단계. 전에는 표준 이름도 아래 알림만 했다 — 표준 정의에 없는 이름·로드된 이름·ByLayer·ByBlock은 전과 같다
        const def = k !== 'BYLAYER' && k !== 'BYBLOCK' && !st.doc.linetypes.has(k) ? STANDARD_LINETYPES.find((d) => d.name === k) : undefined;
        if (def) {
          const lt = makeLinetype(def, st.session.newHandle(), Number(st.doc.header.get('$MEASUREMENT') ?? 1) === 1);
          modifyAll(st, ctx, label, hs, (e) => ({ ...e, linetype: lt.name }) as Entity, [{ kind: 'linetype', key: k, before: null, after: lt }]);
        } else if (k !== 'BYLAYER' && k !== 'BYBLOCK' && !st.doc.linetypes.has(k)) ctx.print(`선종류 "${ft(name)}"을(를) 찾을 수 없습니다. 선종류 관리자(LINETYPE)에서 먼저 로드하십시오.`, 'err');
        else modifyAll(st, ctx, label, hs, (e) => ({ ...e, linetype: k === 'BYLAYER' ? 'ByLayer' : k === 'BYBLOCK' ? 'ByBlock' : st.doc.linetypes.get(k)!.name }) as Entity);
        break;
      }
      case 'S': {
        const v = Number(await ask('새 선종류 축척 지정 <1.0000>:'));
        if (v > 0) modifyAll(st, ctx, label, hs, (e) => ({ ...e, ltscale: v }) as Entity);
        break;
      }
      case 'LW': {
        const t = (await ask('새 선가중치 입력 <BYLAYER>:')) ?? '';
        const up = t.toUpperCase();
        // 표에 없는 값은 가장 가까운 표준 값(203차, Autodesk CHPROP 도움말 「선가중치」: 정해진 값이 아니면 가장 가까운 정해진 값을 준다 —
        // -LAYER 선가중치와 같은 `nearestLineweight`). 전에는 입력 × 100을 그대로 두어(0.29 → 29) 저장 때 DWG는 아래 값(0.25), DXF는 가장 가까운 값(0.30)이 됐다.
        // 음수는 도움말에 말이 없어 받지 않는다(알림 — 객체 값은 그대로). 표준 값·BYLAYER·BYBLOCK·DEFAULT·Enter는 전과 같다
        const mm = Number(t);
        const v = up === '' || up === 'BYLAYER' ? -1 : up === 'BYBLOCK' ? -2 : up === 'DEFAULT' || up === '기본값' ? -3 : Number.isFinite(mm) && mm >= 0 ? nearestLineweight(mm * 100) : NaN;
        if (!Number.isFinite(v)) ctx.print('선가중치는 mm 값(예: 0.25)이나 BYLAYER로 입력하십시오.', 'err');
        else modifyAll(st, ctx, label, hs, (e) => ({ ...e, lineweight: v }) as Entity);
        break;
      }
      case 'T': {
        const v = Number(await ask('새 두께 지정 <0.0000>:'));
        if (Number.isFinite(v)) modifyAll(st, ctx, label, hs, (e) => ({ ...e, thickness: v || undefined }) as Entity);
        break;
      }
      case 'TR': {
        const t = ((await ask('새 투명도 값 입력 [BYLAYER/BYBLOCK] <BYLAYER>:')) ?? '').toUpperCase();
        // 모델 값: -1 도면층별, 0 블록별, 그 밖에는 불투명도(255 = 불투명)
        const v = t === '' || t === 'BYLAYER' ? -1 : t === 'BYBLOCK' ? 0 : Math.round(255 * (1 - Math.min(90, Math.max(0, Number(t))) / 100));
        if (!Number.isFinite(v)) ctx.print('0에서 90 사이의 값을 입력하십시오.', 'err');
        else modifyAll(st, ctx, label, hs, (e) => ({ ...e, transparency: v }) as Entity);
        break;
      }
    }
  }
}

/**
 * 선의 가까운 끝점을 옮기고, 원은 반지름을 바꾸고, 문자는 위치·높이·각도·내용을 묻는다.
 * 원·문자·속성 정의는 찍은 점(WCS 평면도)을 객체 OCS로 옮겨 쓴다(168차, Autodesk CHANGE 도움말 — 문자는 새 삽입점으로 옮기고 원은 반지름을 바꾼다,
 * 고른 객체는 현재 UCS와 평행해야 한다: −Z 객체도 평행하다). 전에는 찍은 점을 OCS 좌표에 그대로 넣어 −Z 문자는 거울상 X 자리로 가고,
 * −Z 원은 OCS 중심과 찍은 점 사이로 반지름을 재어 찍은 점을 지나지 않았다. +Z 객체는 전과 같은 값이다
 */
async function changePoint(app: App, ctx: CommandContext, hs: string[], p: Pt): Promise<void> {
  const st = app.active!;
  const ops: EditOp[] = [];
  for (const h of hs) {
    const e = st.doc.entityIndex.get(h);
    const block = e ? st.session.ownerOf(h) : null;
    if (!e || !block) continue;
    // 자리 짐작(108차 — 찾은 바로 뒤에 단다. 문자·블록 참조는 아래에서 값을 묻는다)
    const at = st.session.slotHint(e.handle);
    const modify = (after: Entity) => ops.push(at === undefined ? { kind: 'modify', block, before: e, after } : { kind: 'modify', block, before: e, after, index: at });
    if (e.type === 'LINE') {
      const ds = Math.hypot(e.start.x - p.x, e.start.y - p.y);
      const de = Math.hypot(e.end.x - p.x, e.end.y - p.y);
      const np = { x: p.x, y: p.y, z: ds <= de ? e.start.z : e.end.z };
      modify(ds <= de ? { ...e, start: np } : { ...e, end: np });
    } else if (e.type === 'CIRCLE') {
      const q = ocsPoint(e.extrusion, e.center.z, p);
      const r = q ? Math.hypot(q.x - e.center.x, q.y - e.center.y) : 0;
      if (r > 1e-12) modify({ ...e, radius: r });
    } else if (e.type === 'TEXT' || e.type === 'ATTDEF') {
      const q = ocsPoint(e.extrusion, e.insert.z, p);
      if (!q) continue;
      const pt = { x: q.x, y: q.y, z: e.insert.z };
      const nh = await ctx.getPoint(`새 높이 지정 <${e.height.toFixed(4)}>:`, { allowText: true, preferNumber: true });
      const na = await ctx.getPoint(`새 회전 각도 지정 <${((e.rotation * 180) / Math.PI).toFixed(0)}>:`, { allowText: true, preferNumber: true });
      const nt = await ctx.getPoint(`새 문자 입력 <${ft(e.text)}>:`, { allowText: true });
      const height = 'text' in nh && Number(nh.text) > 0 ? Number(nh.text) : e.height;
      // 226차: Number가 못 읽은 단위 글자 꼴(`50g` 등)은 그 각(전에는 조용히 앞 각). 못 읽는 글은 전처럼 앞 각
      const ad = 'text' in na ? numberAngleDegrees(na.text) : NaN;
      const rotation = Number.isFinite(ad) ? (ad * Math.PI) / 180 : e.rotation;
      const text = 'text' in nt ? nt.text : e.text;
      const after = { ...e, insert: pt, height, rotation, text } as Entity;
      // 맞춤점을 쓰는 자리맞추기면 맞춤점도 같은 만큼 옮긴다
      if ('alignPoint' in e && e.alignPoint && (e.halign || e.valign)) (after as typeof e).alignPoint = { x: e.alignPoint.x + q.x - e.insert.x, y: e.alignPoint.y + q.y - e.insert.y, z: e.alignPoint.z };
      modify(after);
    } else if (e.type === 'INSERT') {
      const na = await ctx.getPoint(`새 블록 회전 각도 지정 <${((e.rotation * 180) / Math.PI).toFixed(0)}>:`, { allowText: true, preferNumber: true });
      const ad = 'text' in na ? numberAngleDegrees(na.text) : NaN;
      const rotation = Number.isFinite(ad) ? (ad * Math.PI) / 180 : e.rotation;
      const moved = relocateInsert(e, p, rotation);
      if (moved) modify(moved);
    }
  }
  if (ops.length) st.session.commit({ label: 'CHANGE', ops, group: ctx.group });
}

/** OCS 평면(고도 z)의 좌표 → WCS 평면도 좌표, 그 역, 방향(−Z처럼 뒤집힌 평면이면 −1). 평면도로 옮길 수 없으면 null */
function planeOf(ext: Vec3 | undefined, z: number): { to: Affine; back: Affine; sign: number } | null {
  const to = planProj(ext, z);
  const back = affInv(to);
  return back ? { to, back, sign: affDet(to) < 0 ? -1 : 1 } : null;
}

/** 찍은 점(WCS 평면도) → 돌출 방향 ext·고도 z인 OCS 평면의 (x, y). 평면도로 옮길 수 없으면 null */
function ocsPoint(ext: Vec3 | undefined, z: number, p: Pt): Pt | null {
  const pl = planeOf(ext, z);
  return pl ? affApply(pl.back, p) : null;
}

/**
 * CHANGE 변경점의 블록 참조(167차, Autodesk CHANGE 도움말 — 블록은 위치나 회전을 바꾼다): 삽입점을 찍은 점(WCS → 블록 OCS)에 두고 새 회전 각도로 돌린다.
 * 속성은 블록 참조에 딸려 블록과 함께 옮기고 돈다(특성 팔레트의 블록 위치·회전과 같은 뜻) — 맞춘 속성의 맞춤점, 여러 줄 속성의 MTEXT 삽입점·방향까지.
 * 전에는 속성의 삽입점만 옮겨 맞춘 속성·여러 줄 속성이 제자리에 남고 회전을 바꿔도 속성은 돌지 않았으며, 찍은 점을 OCS 삽입점에 그대로 넣어
 * 돌출 방향이 −Z인 블록은 거울상 자리로 갔다. 회전이 그대로면 속성은 블록과 같은 만큼 옮기기만 한다(전과 같은 값)
 */
function relocateInsert(e: InsertEntity, p: Pt, rotation: number): InsertEntity | null {
  const pb = planeOf(e.extrusion, e.insert.z);
  if (!pb) return null;
  const at = affApply(pb.back, p);
  const was = affApply(pb.to, e.insert);
  // WCS 평면도에서 블록이 움직이는 만큼: 옮긴 뒤 찍은 점 둘레로 돈다(블록 OCS가 뒤집혔으면 반대쪽으로)
  const turn = (rotation - e.rotation) * pb.sign;
  let W: Affine = affTranslate(p.x - was.x, p.y - was.y);
  if (turn) W = affMul(affRotate(turn, p), W);
  const r = cloneEntity(e);
  r.insert = { x: at.x, y: at.y, z: e.insert.z };
  r.rotation = rotation;
  for (const a of r.attribs) moveAttrib(a, W, turn);
  return r;
}

/** 속성 하나를 WCS 평면도 변환 W(회전 turn)로 옮긴다 — 삽입점·맞춤점은 속성 OCS, 여러 줄 속성의 MTEXT 삽입점·방향은 WCS */
function moveAttrib(a: AttribEntity, W: Affine, turn: number): void {
  const pa = planeOf(a.extrusion, a.insert.z);
  if (pa) {
    const map = (q: Vec3): Vec3 => {
      const w = affApply(pa.back, affApply(W, affApply(pa.to, q)));
      return { x: w.x, y: w.y, z: q.z };
    };
    a.insert = map(a.insert);
    if (a.alignPoint) a.alignPoint = map(a.alignPoint);
    if (turn) a.rotation += pa.sign * turn;
  }
  const mt = a.mtext;
  if (!mt) return;
  const w = affApply(W, mt.insert);
  mt.insert = { x: w.x, y: w.y, z: mt.insert.z };
  if (!turn) return;
  if (mt.direction) {
    const d = affLin(W, mt.direction);
    mt.direction = { x: d.x, y: d.y, z: mt.direction.z };
  }
  mt.rotation += (planeOf(mt.extrusion, 0)?.sign ?? 1) * turn;
}

/** PDMODE 그림 이름 */
const PDMODES: [number, string][] = [
  [0, '점(·)'],
  [1, '없음'],
  [2, '+'],
  [3, '×'],
  [4, '짧은 세로선'],
  [32, '원 안의 점'],
  [33, '원'],
  [34, '원 안의 +'],
  [35, '원 안의 ×'],
  [36, '원 안의 세로선'],
  [64, '사각형 안의 점'],
  [65, '사각형'],
  [66, '사각형 안의 +'],
  [67, '사각형 안의 ×'],
  [68, '사각형 안의 세로선'],
  [96, '원과 사각형 안의 점'],
  [97, '원과 사각형'],
  [98, '원과 사각형 안의 +'],
  [99, '원과 사각형 안의 ×'],
  [100, '원과 사각형 안의 세로선'],
];

function days(v: HeaderValue | undefined): string {
  if (typeof v !== 'number' || !(v >= 0)) return '-';
  const s = Math.round(v * 86400);
  return `${Math.floor(s / 86400)}일 ${String(Math.floor((s % 86400) / 3600)).padStart(2, '0')}:${String(Math.floor((s % 3600) / 60)).padStart(2, '0')}:${String(s % 60).padStart(2, '0')}`;
}

export function registerPropCommands(app: App): void {
  app.register({
    name: 'CHPROP',
    title: '특성 변경',
    async run(ctx) {
      const hs = await ctx.getSelection('객체 선택:');
      if (hs.length) await changeProps(app, ctx, hs, 'CHPROP');
    },
  });

  app.register({
    name: 'CHANGE',
    aliases: ['-CH'],
    title: '변경',
    async run(ctx) {
      const hs = await ctx.getSelection('객체 선택:');
      if (!hs.length) return;
      const r = await ctx.getPoint('변경점 지정 또는 [특성(P)]:', { keywords: [{ key: 'P', label: '특성' }] });
      if ('keyword' in r) await changeProps(app, ctx, hs, 'CHANGE');
      else if ('point' in r) await changePoint(app, ctx, hs, r.point);
    },
  });

  app.register({
    name: 'COLOR',
    aliases: ['COL', 'COLOUR', 'DDCOLOR'],
    title: '현재 색상',
    transparent: true,
    async run(ctx) {
      const st = app.active!;
      const cur = currentProps(app).color;
      const r = await ctx.getPoint(`새 객체 색상 입력 [트루컬러(T)] <${colorLabel(cur)}>:`, { keywords: [{ key: 'T', label: '트루컬러' }], allowText: true, preferNumber: true });
      let t: string | null = 'text' in r ? r.text : null;
      if ('keyword' in r) {
        const q = await ctx.getPoint('빨강,초록,파랑 값 입력:', { allowText: true });
        t = 'text' in q ? q.text : null;
      }
      if (t === null) return;
      const c = parseColorInput(t);
      if (!c) {
        ctx.print('색상 이름이나 번호(0~256), BYLAYER, BYBLOCK 또는 빨강,초록,파랑 값을 입력하십시오.', 'err');
        return;
      }
      if (c.rgb !== undefined) ctx.print('참고: 현재 색상은 가장 가까운 색상표 색으로 저장됩니다.');
      setHeader(st, ctx, 'COLOR', '$CECOLOR', c.aci);
      app.ui.refreshPalette();
    },
  });

  app.register({
    name: 'DDPTYPE',
    aliases: ['PTYPE'],
    title: '점 스타일',
    async run() {
      const st = app.active!;
      const mode = Number(st.doc.header.get('$PDMODE') ?? 0);
      const size = Number(st.doc.header.get('$PDSIZE') ?? 0);
      const v = await form(
        '점 스타일',
        [
          { key: 'mode', label: '점 모양', type: 'select', value: String(mode), options: PDMODES.map(([m, n]) => ({ value: String(m), label: `${m} — ${n}` })) },
          { key: 'size', label: '점 크기', type: 'number', value: Math.abs(size) || 5 },
          { key: 'rel', label: '화면에 상대적인 크기 설정(%)', type: 'check', value: size <= 0 },
        ],
        { validate: (x) => (Number(x.size) > 0 ? null : '점 크기는 0보다 커야 합니다.') },
      );
      if (!v) return;
      const ops: EditOp[] = [];
      const nm = Number(v.mode);
      const ns = v.rel ? -Number(v.size) : Number(v.size);
      if (nm !== mode) ops.push({ kind: 'header', name: '$PDMODE', before: st.doc.header.get('$PDMODE'), after: nm });
      if (ns !== size) ops.push({ kind: 'header', name: '$PDSIZE', before: st.doc.header.get('$PDSIZE'), after: ns });
      if (ops.length) st.session.commit({ label: 'DDPTYPE', ops });
    },
  });

  app.register({
    name: 'ATTDISP',
    title: '속성 표시',
    transparent: true,
    async run(ctx) {
      const st = app.active!;
      const cur = Number(st.doc.header.get('$ATTMODE') ?? 1);
      const r = await ctx.getPoint(`속성 가시성 설정 입력 [보통(N)/켜기(ON)/끄기(OFF)] <${cur === 0 ? '끄기' : cur === 2 ? '켜기' : '보통'}>:`, {
        keywords: [
          { key: 'N', label: '보통' },
          { key: 'ON', label: '켜기' },
          { key: 'OFF', label: '끄기' },
        ],
      });
      if (!('keyword' in r)) return;
      setHeader(st, ctx, 'ATTDISP', '$ATTMODE', r.keyword === 'OFF' ? 0 : r.keyword === 'ON' ? 2 : 1);
    },
  });

  app.register({
    name: 'SOLID',
    aliases: ['SO'],
    title: '2D 솔리드',
    async run(ctx) {
      const st = app.active!;
      const get = async (prompt: string, base: Pt | null, enterEnds: boolean): Promise<Pt | null> => {
        const r = await ctx.getPoint(prompt, { base });
        if ('point' in r) return r.point;
        if ('enter' in r && enterEnds) return null;
        return null;
      };
      let a = await get('첫 번째 점 지정:', null, false);
      if (!a) return;
      let b = await get('두 번째 점 지정:', a, false);
      if (!b) return;
      for (;;) {
        const c = await get('세 번째 점 지정:', b, true);
        if (!c) return;
        const d = await get('네 번째 점 지정 또는 <종료>:', c, true);
        // 205차: 점 Z는 현재 고도(ELEVATION, 배치는 PELEVATION — Autodesk ELEV 도움말: X·Y만 준 점의 Z가 현재 고도이고 두께는 그 고도에서 돌출).
        // 전에는 늘 0이라 두께(currentProps의 THICKNESS)는 받으면서 바닥은 0에 있었다. LINE·PLINE·ARC·TRACE·3DFACE와 같은 `currentElevation`.
        // 입력이 Z를 준 점은 PLINE·ARC처럼 받지 않는다(2D 객체의 평면을 어느 점의 Z로 정하는지 도움말에 없음 — ROADMAP)
        const elev = currentElevation(app);
        const z = (p: Pt) => ({ x: p.x, y: p.y, z: elev });
        const e: FaceEntity = { ...currentProps(app), type: 'SOLID', handle: '', points: [z(a), z(b), z(c), z(d ?? c)], invisibleEdges: 0 };
        addEntities(app, ctx, [e as Entity], 'SOLID');
        if (!d) return;
        a = c;
        b = d;
        void st;
      }
    },
  });

  app.register({
    name: 'TIME',
    title: '도면 시간',
    noDoc: false,
    run(ctx) {
      const st = app.active!;
      const hd = st.doc.header;
      ctx.print(`현재 시간:              ${dateTimeText(new Date())}`);
      ctx.print(`이 도면의 시간:`);
      // 저장한 곳의 현지 시각 그대로(시간대를 더하지 않음 — 도면 비교·DWGPROPS와 같은 길 datetext.ts, 346차)
      ctx.print(`  작성:                 ${drawingTimeText(hd, '$TDCREATE') || '-'}`);
      ctx.print(`  마지막 업데이트:      ${drawingTimeText(hd, '$TDUPDATE') || '-'}`);
      ctx.print(`  총 편집 시간:         ${uiText(days(hd.get('$TDINDWG')))}`);
      ctx.print(`  경과 타이머(켜기):    ${uiText(days(hd.get('$TDUSRTIMER')))}`);
    },
  });
}
